using UnityEngine;
using UnityEngine.UI;
using TMPro;

public sealed partial class GridShiftCampaignUI {
 GameObject socialRoot;GridShiftCitizen socialOwner;TMP_Text socialPlayer,socialNpc,socialPlayerName,socialNpcName;int previousReply=-1,previousTopic=-1;
 public GridShiftCitizen SocialOwner=>socialOwner;
 void BuildSocial(){socialRoot=new GameObject("Corner social conversation",typeof(RectTransform));socialRoot.transform.SetParent(root.transform,false);var r=(RectTransform)socialRoot.transform;GridShiftUI.Stretch(r,Vector2.zero,Vector2.zero);
  var speech=GridShiftUI.Rect("Dialogue transcript",r,new Vector2(1315,270));speech.anchorMin=speech.anchorMax=Vector2.zero;speech.pivot=Vector2.zero;speech.anchoredPosition=new Vector2(28,28);GridShiftDialogueStyle.Surface(speech.gameObject.AddComponent<Image>());GridShiftUITheme.Art(speech,"GS_Simbolo_Transparente",new Vector2(48,48),new Vector2(-610,101));
  socialPlayerName=Label(speech,"",20,new Vector2(102,-35),new Vector2(1170,30));socialPlayerName.color=new Color(1,.82f,.2f);socialPlayer=Label(speech,"",23,new Vector2(36,-74),new Vector2(1220,48));socialNpcName=Label(speech,"",20,new Vector2(36,-143),new Vector2(1170,30));socialNpcName.color=new Color(.34f,.75f,1);socialNpc=Label(speech,"",23,new Vector2(36,-184),new Vector2(1220,70));
  var choices=GridShiftUI.Rect("NPC actions bottom right",r,new Vector2(505,678));choices.anchorMin=choices.anchorMax=Vector2.right;choices.pivot=Vector2.right;choices.anchoredPosition=new Vector2(-28,28);GridShiftDialogueStyle.Surface(choices.gameObject.AddComponent<Image>());var stack=choices.gameObject.AddComponent<VerticalLayoutGroup>();stack.padding=new RectOffset(22,22,20,20);stack.spacing=7;stack.childControlHeight=false;stack.childControlWidth=true;stack.childForceExpandHeight=false;GridShiftUI.Text(choices,"CONVERSAR",23,36).color=new Color(1,.82f,.2f);
  for(int i=0;i<GridShiftDialogueBank.Topics.Length;i++){int topic=i;var row=GridShiftUI.Rect(GridShiftDialogueBank.Topics[i],choices,new Vector2(460,45));var image=row.gameObject.AddComponent<Image>();image.color=new Color(.045f,.2f,.36f,.98f);var button=row.gameObject.AddComponent<Button>();button.targetGraphic=image;var colors=button.colors;colors.normalColor=Color.white;colors.highlightedColor=new Color(.4f,.78f,1);colors.selectedColor=colors.highlightedColor;colors.pressedColor=new Color(.18f,.5f,.8f);button.colors=colors;button.onClick.AddListener(()=>ChooseSocial(topic));var text=GridShiftUI.Text(row,GridShiftDialogueBank.Topics[i],22,45);GridShiftUI.Stretch(text.rectTransform,new Vector2(18,3),new Vector2(-16,-3));text.alignment=TextAlignmentOptions.MidlineLeft;}
  var close=GridShiftUI.Button(choices,"Encerrar conversa",Close,45);socialRoot.SetActive(false);
 }
 static TMP_Text Label(Transform parent,string value,int size,Vector2 at,Vector2 bounds){var t=GridShiftUI.Text(parent,value,size,bounds.y);t.rectTransform.anchorMin=t.rectTransform.anchorMax=new Vector2(0,1);t.rectTransform.pivot=new Vector2(0,1);t.rectTransform.anchoredPosition=at;t.rectTransform.sizeDelta=bounds;t.richText=false;return t;}
 public void OpenCitizen(GridShiftCitizen citizen,PlayerMovement player){Open(citizen.Nickname,"");if(socialRoot==null)BuildSocial();socialOwner=citizen;citizen.PauseConversation(true);previousReply=previousTopic=-1;panel.gameObject.SetActive(false);root.GetComponent<Image>().color=Color.clear;socialRoot.SetActive(true);socialPlayerName.text=GridShiftCharacter.PlayerName+" · VOCÊ";socialNpcName.text=citizen.Nickname;socialPlayer.text="Quero conversar um pouco.";socialNpc.text=GridShiftLife.Instance?.CitizenComment()??GridShiftDialogueBank.Introduction();}
 public void ChooseSocial(int topic){if(socialOwner==null)return;int next;var exchange=GridShiftDialogueBank.Pick(topic,previousTopic==topic?previousReply:-1,socialOwner.Warmth,out next);previousReply=next;previousTopic=topic;socialPlayerName.text=GridShiftCharacter.PlayerName+" · VOCÊ";socialPlayer.text=exchange.player;socialNpcName.text=socialOwner.Nickname;socialNpc.text=exchange.npc+(GridShiftLife.Instance?.CitizenComment() is string comment?"\n"+comment:"");socialOwner.React(topic);}
 void EndSocial(){if(socialOwner!=null)socialOwner.PauseConversation(false);socialOwner=null;if(socialRoot!=null)socialRoot.SetActive(false);if(panel!=null)panel.gameObject.SetActive(true);}
 public void CloseCitizen(GridShiftCitizen citizen){if(socialOwner==citizen)Close();}
}

