 };
 static readonly string[] introductions={"Oi! Podemos conversar um pouco.","Olá! O que você gostaria de dizer?","Oi! Tudo certo por aí?","Pode falar, estou ouvindo.","Um encontro inesperado! Como vai?","Olá! Um pouco de conversa cai bem."};
 public static int AuthoredReplyCount{get{int count=0;foreach(var row in replies)count+=row.Length;return count;}}
 public static string Introduction()=>introductions[Random.Range(0,introductions.Length)];
 public static Exchange Pick(int topic,int previous,int warmth,out int chosen){topic=Mathf.Clamp(topic,0,Topics.Length-1);chosen=Random.Range(0,replies[topic].Length);if(chosen==previous)chosen=(chosen+1)%replies[topic].Length;string context=topic==2?(GridShiftWeather.Raining?" Hoje, com essa chuva, prefiro ir com calma.":WorldSession.Instance!=null&&WorldSession.Instance.ClockHour>=18?" À noite eu presto ainda mais atenção no caminho.":""):"";string mood=warmth<=-2&&topic<7?"Ainda estou chateado, mas vou responder. ":"";return new Exchange{player=player[topic][Random.Range(0,player[topic].Length)],npc=mood+replies[topic][chosen]+context};}
}
